import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 89 For sale","description":"学习 since 与 for，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 89 For sale","description":"学习 since 与 for，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 since 与 for，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 88 Have you ... yet?","link":"/life/english/new-concept/book-1/unit-04/lesson-088"},"next":{"text":"第一册：英语初阶 · Lesson 90 Have you ... yet?","link":"/life/english/new-concept/book-1/unit-04/lesson-090"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 88 Have you ... yet?","link":"/life/english/new-concept/book-1/unit-04/lesson-088"},"next":{"text":"第一册：英语初阶 · Lesson 90 Have you ... yet?","link":"/life/english/new-concept/book-1/unit-04/lesson-090"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-089.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-089.md"}'),i={name:"life/english/new-concept/book-1/unit-04/lesson-089.md"};function s(r,e,l,h,c,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-89-for-sale" tabindex="-1">第一册：英语初阶 · Lesson 89 For sale <a class="header-anchor" href="#第一册-英语初阶-·-lesson-89-for-sale" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 89 For sale&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-090">配套课 Lesson 90</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>询问居住年限和持续状态 本课要掌握since 与 for，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>sale</td><td>/seɪl/</td><td>n.</td><td>出售</td><td>for sale</td></tr><tr><td>price</td><td>/praɪs/</td><td>n.</td><td>价格</td><td>ask the price</td></tr><tr><td>since</td><td>/sɪns/</td><td>prep.</td><td>自从</td><td>since 2020</td></tr><tr><td>owner</td><td>/ˈəʊnə/</td><td>n.</td><td>主人</td><td>the house owner</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>for sale — 待售</li><li>how long — 询问持续多久</li></ul><h2 id="语法讲解-since-与-for" tabindex="-1">语法讲解：since 与 for <a class="header-anchor" href="#语法讲解-since-与-for" aria-label="Permalink to &quot;语法讲解：since 与 for&quot;">​</a></h2><p>现在完成时可以描述从过去延续到现在的状态。for 后接时长，如 for six years；since 后接起点，如 since 2020 或 since I moved here。问持续多久用 How long have you ...?。并非所有动词都能直接接持续时长：买到某物是瞬间事件，表达已拥有多久常用 have had，而不直接说 have bought for。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We have lived here for six years.</p></blockquote><p>我们已经在这里住了六年。</p><p>Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>since 后不是 six years 这种时长；for six years 与 since 2020 不要混淆。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“We have lived here for six years.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We have lived here for six years. She has owned this flat since 2020.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“询问居住年限和持续状态”写两至三句，再读给同伴听。至少使用一次since 与 for，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。 Has owned 表持续的拥有状态；since 2020 给出起点，与延续到现在的状态配合。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 since/for：We have lived here ___ six years.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> for</p><p><strong>解析：</strong> 按本课规则判断：现在完成时可以描述从过去延续到现在的状态。for 后接时长，如 for six years；since 后接起点，如 since 2020 或 since I moved here。问持续多久用 How long have you ...?。并非所有动词都能直接接持续时长：买到某物是瞬间事件，表达已拥有多久常用 have had，而不直接说 have bought for。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我们已经在这里住了六年。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We have lived here for six years.</p><p><strong>解析：</strong> Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：She has owned this flat since 2020.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 她从2020年起就拥有这套公寓。</p><p><strong>解析：</strong> Has owned 表持续的拥有状态；since 2020 给出起点，与延续到现在的状态配合。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：since 与 for。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-088">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-090">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",s]]);export{u as __pageData,f as default};
